CREATE POLICY "Academy docs own read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'academy-documents' AND ((storage.foldername(name))[1] = auth.uid()::text OR public.has_role(auth.uid(),'admin')));
CREATE POLICY "Academy docs own upload" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'academy-documents' AND (storage.foldername(name))[1] = auth.uid()::text);
CREATE POLICY "Academy docs own delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'academy-documents' AND (storage.foldername(name))[1] = auth.uid()::text);